#[test]
fn string_lines_length_0() {
    let s: &str = "";
    assert_eq!(s.split_inclusive('\n').count() as i64, 0);
}

#[test]
fn string_lines_length_1() {
    let s: &str = "a";
    assert_eq!(s.split_inclusive('\n').count() as i64, 1);
}

#[test]
fn string_lines_length_2() {
    let s: &str = "a\u{a}";
    assert_eq!(s.split_inclusive('\n').count() as i64, 1);
}

#[test]
fn string_lines_length_3() {
    let s: &str = "a\u{a}b";
    assert_eq!(s.split_inclusive('\n').count() as i64, 2);
}

