fn string_lines_length_6() {
    let s: &str = "a\u{d}\u{a}b";
    assert_eq!(s.split_inclusive('\n').count() as i64, 2);
}

#[test]
fn string_int_int_0() {
    let s: &str = "hello";
    let start: i64 = 1;
    let len: i64 = 3;
    assert_eq!({ let cs: Vec<char> = s.chars().collect(); let n = cs.len() as i64; let mut st = start; if st < 0 { st += n; } if st < 0 || st > n || len < 0 { None } else { let en = st.saturating_add(len).min(n); Some(cs[st as usize..en as usize].iter().collect::<String>()) } }, Some("ell".to_string()));
}

