#[test]
fn string_0() {
    let s: &str = "ab";
    let count: i64 = 3;
    assert_eq!(if count < 0 { Err(()) } else { Ok(s.repeat(count as usize)) }.unwrap(), "ababab");
}

#[test]
fn string_1() {
    let s: &str = "ab";
    let count: i64 = 0;
    assert_eq!(if count < 0 { Err(()) } else { Ok(s.repeat(count as usize)) }.unwrap(), "");
}

#[test]
fn string_2() {
    let s: &str = "";
    let count: i64 = 5;
    assert_eq!(if count < 0 { Err(()) } else { Ok(s.repeat(count as usize)) }.unwrap(), "");
}

#[test]
fn string_3() {
    let s: &str = "\u{65e5}";
    let count: i64 = 2;
    assert_eq!(if count < 0 { Err(()) } else { Ok(s.repeat(count as usize)) }.unwrap(), "\u{65e5}\u{65e5}");
}

#[test]
fn string_4() {
    let s: &str = "ab";
    let count: i64 = -1;
    assert!(if count < 0 { Err(()) } else { Ok(s.repeat(count as usize)) }.is_err());
}

